rules.logic:
// Move the horoscope convenience bar to sit directly after the sticky header
const header = document.querySelector('header#module-uh');
if (!header || !element.parentNode) return;
// Check if already repositioned
if (element.previousElementSibling === header || element.getAttribute('data-repositioned') === 'horoscope') return;
// Wrap body-level placement: insert after header in its parent
const headerParent = header.parentNode;
if (!headerParent) return;
headerParent.insertBefore(element, header.nextSibling);
element.setAttribute('data-repositioned', 'horoscope');
element.style.position = 'sticky';
element.style.top = '56px';
element.style.zIndex = '15';
element.style.backgroundColor = 'var(--color-bg-primary, #fff)';
element.style.paddingTop = '8px';
element.style.paddingBottom = '4px';
element.style.borderBottom = '1px solid var(--color-border-tertiary, #e0e0e0)';

// Move the "From Our Shopping Experts" li to be the first item in the feed list
const feed = document.querySelector('#strm > ul.flex');
if (!feed || !element.parentNode) return;
// Already first child of feed, skip
if (feed.firstElementChild === element && element.getAttribute('data-repositioned') === 'shopping') return;
feed.insertBefore(element, feed.firstElementChild);
element.setAttribute('data-repositioned', 'shopping');
element.style.borderRadius = '10px';
element.style.background = 'var(--color-bg-brand-secondary, #f4f0ff)';
element.style.padding = '16px';
element.style.marginBottom = '8px';

// Hide feed items tagged as Politics or with military/political keywords
const anchor = element.querySelector('a[data-yga]');
if (!anchor) return;

const yga = anchor.getAttribute('data-yga') || '';
const ylk = anchor.getAttribute('data-ylk') || '';
const headlineEl = element.querySelector('h3 a');
const headline = headlineEl ? headlineEl.textContent.toLowerCase() : '';

// Category-based filter
let isPolitical = false;
try {
  const data = JSON.parse(yga);
  const category = (data.yContentCategory || '').toLowerCase();
  const labels = (data.yLabels || '').toLowerCase();
  if (category === 'politics' || category === 'u.s.' || labels.includes('politics')) {
    isPolitical = true;
  }
} catch(e) {}

// Keyword-based filter for political & military topics
const politicalKeywords = [
  'trump', 'biden', 'congress', 'senate', 'democrat', 'republican',
  'election', 'white house', 'politics', 'political', 'president',
  'administration', 'military', 'pentagon', 'missile', 'war', 'troops',
  'iran', 'ukraine', 'nato', 'defense', 'weapons', 'strike', 'bomb',
  'army', 'navy', 'air force', 'soldier', 'general ', 'sanctions',
  'diplomacy', 'diplomat', 'secretary of state', 'legislation', 'bill passed',
  'gun control', 'border', 'immigration', 'tariff', 'sanctions', 'nuclear'
];

if (!isPolitical) {
  for (const kw of politicalKeywords) {
    if (headline.includes(kw)) {
      isPolitical = true;
      break;
    }
  }
}

// Also check ylk badge labels
if (ylk.includes('badge-politics') || ylk.includes('ll4:badge-news') && ylk.includes('cnt_tpc:Politics')) {
  isPolitical = true;
}

element.style.display = isPolitical ? 'none' : '';

const anchor = element.querySelector('a[data-yga]');
if (!anchor) return;

const yga = anchor.getAttribute('data-yga') || '';
const headline = element.querySelector('h3 a') ? element.querySelector('h3 a').textContent.toLowerCase() : '';

let isPolitical = false;
try {
  const data = JSON.parse(yga);
  const category = (data.yContentCategory || '').toLowerCase();
  if (category === 'politics' || category === 'world') isPolitical = true;
} catch(e) {}

const politicalKeywords = [
  'trump', 'biden', 'congress', 'senate', 'democrat', 'republican',
  'election', 'white house', 'military', 'pentagon', 'missile', 'war',
  'iran', 'ukraine', 'nato', 'defense', 'weapons', 'strike', 'bomb',
  'army', 'navy', 'general ', 'sanctions', 'diplomacy', 'nuclear',
  'lawyer', 'administration', 'kennedy center', 'tariff', 'border'
];

if (!isPolitical) {
  for (const kw of politicalKeywords) {
    if (headline.includes(kw)) { isPolitical = true; break; }
  }
}

element.style.display = isPolitical ? 'none' : '';
